package main

import (
 "embed"
 "fmt"
 "regexp"
 "strconv"
 "strings"
)

//go:embed usage/*.txt
var helpFiles embed.FS

type option struct { name, short, kind, def string }
var groups = map[string]map[string]option{}
var allOptions = map[string]option{}
var commands = []string{"add-environment", "diff", "format", "help", "init", "lint", "pull", "push", "version"}

func setupOptions() {
 for _,cmd:=range commands {
  groups[cmd]=map[string]option{}
  text,_:=helpFiles.ReadFile("usage/help-"+cmd+".txt")
  for _,line:=range strings.Split(string(text),"\n") {
   p:=strings.Index(line,"--"); if p<0 || !strings.HasPrefix(line," ") {continue}
   s:=line[p+2:]; kind:="bool"; def:=""; name:=""
   if strings.HasPrefix(s,"[skip-]") {s=s[7:];def="1"}
   j:=0;for j<len(s)&&((s[j]>='a'&&s[j]<='z')||s[j]=='-'||s[j]>='0'&&s[j]<='9') {j++}
   if j==0 {continue};name=s[:j];s=s[j:]
   if strings.HasPrefix(s,"[=value]") {kind="optional"} else if strings.HasPrefix(s," value") {kind="value"}
   if i:=strings.LastIndex(line," (default \""); i>=0 {
    q:=line[i+10:];if k:=strings.LastIndex(q,"\"");k>=0 {def=q[:k]}
   }
   short:="";if strings.HasPrefix(line,"  -") && len(line)>4&&line[4]==',' {short=line[3:4]}
   o:=option{name,short,kind,def}; groups[cmd][name]=o; allOptions[name]=o
  }
 }
 // Options usable in option files, and the intentionally quiet connection options.
 globals:=map[string]option{}
 for k,v:=range groups["version"] {globals[k]=v}
 for _,o:=range []option{{"host","","value",""},{"schema","","value",""},{"port","P","value","3306"},{"socket","S","value","/tmp/mysql.sock"},{"flavor","","value",""},{"generator","","value",""},{"default-character-set","","value",""},{"default-collation","","value",""}} {globals[o.name]=o;allOptions[o.name]=o}
 groups[""]=globals
 for _,cmd:=range commands {for k,v:=range globals {if _,ok:=groups[cmd][k];!ok {groups[cmd][k]=v}}}
 for _,cmd:=range []string{"diff","push"} {
  for _,o:=range []option{{"dry-run","","bool",""},{"brief","q","bool",""},{"foreign-key-checks","","bool",""}} {groups[cmd][o.name]=o;allOptions[o.name]=o}
 }
}

type value struct { text, source string; bare bool }
type config map[string]value
func (c config) get(k string) string { if v,ok:=c[k];ok {return expandValue(v.text)};return allOptions[k].def }
func (c config) has(k string) bool {_,ok:=c[k];return ok}
func (c config) boolean(k string) bool {return truth(c.get(k))}
func (c config) clone() config {r:=config{};for k,v:=range c {r[k]=v};return r}
func truth(s string) bool {s=strings.ToLower(s);return s!=""&&s!="0"&&s!="false"&&s!="off"}
func normalize(s string) (name string, mode int,loose bool) {
 s=strings.ToLower(strings.ReplaceAll(s,"_","-"))
 if strings.HasPrefix(s,"loose-") {s=s[6:];loose=true}
 if strings.HasPrefix(s,"skip-") {s=s[5:];mode=-1} else if strings.HasPrefix(s,"disable-") {s=s[8:];mode=-1} else if strings.HasPrefix(s,"enable-") {s=s[7:];mode=1}
 return s,mode,loose
}
type invocation struct {cmd string;args []string;opts config;help bool;helpTarget string;version bool}
func parseCLI(args []string) (inv invocation,err error) {
 inv.opts=config{}; options:=true
 for i:=0;i<len(args);i++ {
  s:=args[i]
  if options && s=="--" {options=false;continue}
  if options&&len(s)>1&&s[0]=='-' {
   long:=strings.HasPrefix(s,"--");tokens:=s[1:]
   if long {tokens=s[2:]}
   for len(tokens)>0 {
    key:=tokens;val:="";explicit:=false
    if long {if p:=strings.IndexByte(key,'=');p>=0 {val=key[p+1:];key=key[:p];explicit=true};tokens=""} else {key=tokens[:1];tokens=tokens[1:]}
    name,mode,loose:=normalize(key)
    o,exists:=groups[inv.cmd][name]
    if !long {exists=false;for _,cand:=range groups[inv.cmd] {if cand.short==key {o=cand;name=cand.name;exists=true;break}}}
    if !exists&&!loose {return inv,fmt.Errorf("CLI: Unknown option %q",name)}
    if !exists {continue}
    if !long&&o.kind!="bool"&&len(tokens)>0 {val=tokens;explicit=true;tokens=""}
    bare:=false
    if !explicit {
     if mode<0 {val=""} else if o.kind=="value"&&mode==0 {
      if i+1>=len(args)||strings.HasPrefix(args[i+1],"-") {return inv,fmt.Errorf("CLI: Missing required value for option %s",name)}
      i++;val=args[i]
     } else {val="1";bare=true}
    }
    if mode<0 {val="";bare=false}
    inv.opts[name]=value{val,"CLI",bare}
   }
  } else if inv.cmd=="" {
   if _,ok:=groups[s];!ok||s=="" {return inv,fmt.Errorf("Unknown command %q",s)}
   inv.cmd=s
  } else {
   max:=1;if inv.cmd=="version" {max=0}
   if len(inv.args)>=max {return inv,fmt.Errorf("Extra command-line arg %q supplied; command %s takes a max of %d args",s,inv.cmd,max)}
   inv.args=append(inv.args,s)
  }
 }
 for _,key:=range []string{"host","schema"} {
  if inv.opts.has(key) && !(key=="host"&&(inv.cmd=="init"||inv.cmd=="add-environment")) && !(key=="schema"&&inv.cmd=="init") {return inv,fmt.Errorf("The %s option cannot be set via command line for this command. For more information, visit https://www.skeema.io/docs/config/#limitations-on-host-and-schema-options",key)}
 }
 if v,ok:=inv.opts["help"];ok&&v.text!="" {inv.help=true; inv.helpTarget=inv.cmd;if inv.cmd==""||inv.cmd=="help" {if !v.bare {inv.helpTarget=v.text}else {inv.helpTarget=""}}}
 inv.version=inv.opts.boolean("version")
 if inv.cmd=="add-environment"&&len(inv.args)==0&&!inv.help&&!inv.version {return inv,fmt.Errorf("Too few positional args supplied on command line; command add-environment requires at least 1 args")}
 return inv,nil
}
func helpText(cmd string) (string,error) {
 if cmd==""||cmd=="help" {cmd="help"}
 b,e:=helpFiles.ReadFile("usage/help-"+cmd+".txt");if e!=nil {return "",fmt.Errorf("Unknown command %q",cmd)}
 // Text was measured from the command-line interface, including blank lines.
 return string(b),nil
}
func enumCheck(c config,key string,allowed ...string) error {
 s:=strings.ToLower(c.get(key));if s=="" {return nil};for _,a:=range allowed {if s==a {return nil}}
 q:=[]string{};for _,a:=range allowed {q=append(q,strconv.Quote(a))};return fmt.Errorf("Option %s can only be set to one of these values: %s",key,strings.Join(q,", "))
}
func regexCheck(c config) error {for _,k:=range []string{"ignore-table","ignore-proc","ignore-func"} {if s:=c.get(k);s!="" {if _,e:=regexp.Compile(s);e!=nil{return fmt.Errorf("Invalid regexp for option %s: %s",k,s)}}};return nil}
EOF"}

