package main

import (
 "strings"
 "testing"
)

func TestCommandLine(t *testing.T) {
 setupOptions()
 tests:=[]struct{args []string;cmd string;errorText string}{
  {[]string{"lint","--skip-format","staging"},"lint",""},
  {[]string{"init","-h127.0.0.1","-P3307"},"init",""},
  {[]string{"help","lint"},"help",""},
  {[]string{"--help=lint"},"",""},
  {[]string{"--loose-future-feature","version"},"version",""},
  {[]string{"lint","--host=db"},"","The host option cannot be set via command line"},
  {[]string{"--workspace=docker","lint"},"","CLI: Unknown option \"workspace\""},
  {[]string{"init","--port"},"","CLI: Missing required value for option port"},
  {[]string{"version","extra"},"","Extra command-line arg \"extra\" supplied; command version takes a max of 0 args"},
  {[]string{"add-environment"},"","Too few positional args supplied on command line"},
 }
 for _,test:=range tests {
  inv,e:=parseCLI(test.args)
  if test.errorText!="" {if e==nil||!strings.Contains(e.Error(),test.errorText){t.Errorf("%v: got %v; want %s",test.args,e,test.errorText)};continue}
  if e!=nil||inv.cmd!=test.cmd{t.Errorf("%v: command %q, error %v",test.args,inv.cmd,e)}
 }
}

func TestOptionDefaults(t *testing.T) {
 setupOptions();c:=config{}
 for k,want:=range map[string]string{"user":"root","port":"3306","socket":"/tmp/mysql.sock","workspace":"temp-schema","temp-schema":"_skeema_tmp","concurrent-servers":"1"} {
  if got:=c.get(k);got!=want {t.Errorf("%s: got %q, want %q",k,got,want)}
 }
 if !c.boolean("format")||!c.boolean("write")||c.boolean("debug"){t.Error("unexpected boolean defaults")}
}
func TestAllHelpTopics(t *testing.T) {
 for _,cmd:=range commands {
  text,e:=helpText(cmd);if e!=nil||!strings.Contains(text,"Usage:  skeema")||!strings.HasSuffix(text,"\n\n"){t.Errorf("invalid help topic %s",cmd)}
 }
 if _,e:=helpText("nonexistent");e==nil{t.Error("unknown help topic accepted")}
}
EOF
