package main

import (
 "os"
 "path/filepath"
 "strings"
 "testing"
)
func TestOptionFile(t *testing.T) {
 setupOptions();dir:=t.TempDir();path:=filepath.Join(dir,".skeema")
 text:="# comment\nuser='application'\nskip-format\n[production]\nhost=localhost\n[dev]\nhost=127.0.0.1\nport=3307\n"
 if e:=os.WriteFile(path,[]byte(text),0600);e!=nil{t.Fatal(e)}
 f,e:=readOptions(path,false);if e!=nil{t.Fatal(e)}
 c:=config{};f.apply(c,"dev")
 if c.get("host")!="127.0.0.1"||c.get("port")!="3307"||c.get("user")!="application"||c.boolean("format"){t.Fatalf("wrong config: %v",c)}
 want:="skip-format\nuser='application'\n\n[production]\nhost=localhost\n\n[dev]\nhost=127.0.0.1\nport=3307\n"
 if got:=string(f.serialize());got!=want{t.Errorf("serialization:\n%s\nwant:\n%s",got,want)}
}
func TestOptionFileErrors(t *testing.T) {
 setupOptions();path:=filepath.Join(t.TempDir(),".skeema")
 tests:=map[string]string{"[foo":"unterminated section name","[foo] junk":"extra characters after section name","host":"Missing required value for option host","user=\"unterminated":"Quoted value has no terminating quote","unrecognized=1":"Unknown option \"unrecognized\""}
 for input,want:=range tests {
  os.WriteFile(path,[]byte(input),0600);_,e:=readOptions(path,false)
  if e==nil||!strings.Contains(e.Error(),want){t.Errorf("%q: %v",input,e)}
 }
}
func TestEnvironmentExpansion(t *testing.T) {
 setupOptions();t.Setenv("SCHEMA_TEST_USER","alice")
 c:=config{"user":{text:"$SCHEMA_TEST_USER",source:"options",raw:"\"$SCHEMA_TEST_USER\""}}
 if c.get("user")!="alice"{t.Error("file variable not expanded")}
 c["user"]=value{text:"$SCHEMA_TEST_USER",source:"CLI"}
 if c.get("user")!="$SCHEMA_TEST_USER"{t.Error("command line should be literal")}
 c["user"]=value{text:"$SCHEMA_TEST_USER",source:"options",raw:"'$SCHEMA_TEST_USER'"}
 if c.get("user")!="$SCHEMA_TEST_USER"{t.Error("single quotes should be literal")}
}
EOF
