package main

import (
 "strings"
 "testing"
)
func TestSQLStatements(t *testing.T) {
 sql:="-- a heading\nCREATE TABLE `orders`(id int);\n\n SELECT 1;\nDELIMITER $$\nCREATE PROCEDURE p() BEGIN SELECT 1; SELECT 2; END$$\nDELIMITER ;\nUSE other;\nCREATE TABLE t(id int);"
 result,e:=lexSQL(sql,"test.sql");if e!=nil{t.Fatal(e)}
 want:=[]string{"table","unknown","procedure","use","table"}
 if len(result)!=len(want){t.Fatalf("got %d statements, want %d",len(result),len(want))}
 for i,s:=range result {if s.kind!=want[i]{t.Errorf("statement %d: %s",i,s.kind)}}
 if result[1].line!=4||result[1].col!=2 {t.Errorf("bad location: %s",result[1].loc())}
 if result[4].schema!="other"{t.Error("USE did not select schema")}
}
func TestCompoundRoutine(t *testing.T) {
 result,e:=lexSQL("CREATE PROCEDURE p() BEGIN SELECT 1; BEGIN SELECT 2; END; END; SELECT 3;","routine.sql")
 if e!=nil{t.Fatal(e)}
 if len(result)!=2||result[0].kind!="procedure"||result[1].kind!="unknown"{t.Fatalf("bad statements: %+v",result)}
}
func TestLexicalErrors(t *testing.T) {
 for input,want:=range map[string]string{"SELECT 'unclosed":"String is missing closing quote at line 1, column 8","SELECT `unclosed":"Identifier is missing closing quote at line 1, column 8","\n/* open":"Comment starting with /* is never closed at line 2"} {
  _,e:=lexSQL(input,"x.sql");if e==nil||!strings.Contains(e.Error(),want){t.Errorf("%s: %v",input,e)}
 }
}
func TestTableSelection(t *testing.T) {
 for input,want:=range map[string]string{"CREATE TABLE t(id int);":"table","CREATE TABLE t AS SELECT 1;":"unknown","CREATE TEMPORARY TABLE t(id int);":"unknown","CREATE VIEW v AS SELECT 1;":"unknown","CREATE OR REPLACE TABLE t(id int);":"table","CREATE FUNCTION f() RETURNS INT RETURN 1;":"function"} {
  r,e:=lexSQL(input,"x.sql");if e!=nil||len(r)!=1||r[0].kind!=want{t.Errorf("%s: %v, %v",input,r,e)}
 }
}
EOF
